// src/lib/plattform/backend/leadkette.js
//
// Backend-Teil „Lead-Kette“ (Welle 2, Paket B3) – eigene Schnittstelle, backend/index.js bleibt unverändert.
// Auswahl wie backend(): Frappe bei PLATTFORM_BACKEND=frappe, sonst Demo. Nur serverseitig verwenden.
//
// ── VERTRAG FÜR B4 (Bericht/DOI) und alle Versandstellen ─────────────────────────────────────────────────────
//
//   import { protokollAnhaengen, werbekanalErlaubt, werbekanalSicherstellen } from "@/lib/plattform/backend/leadkette";
//
//   await protokollAnhaengen({
//     email,                 // ODER pseudonym (64 Hex) – das Pseudonym berechnet der Server (HMAC-SHA-256 + Pepper)
//     art: "einwilligung" | "doi" | "widerruf" | "hinweis",
//     zweck: "bericht" | "newsletter" | "werbeanruf" | "weitergabe_partner"   (hinweis: nur "anfrage"),
//     textId: "bericht_doi",           // /^[a-z][a-z0-9_.-]{0,59}$/
//     textVersion: "ENTWURF-2026-10-03",// /^[A-Za-z][A-Za-z0-9_.:-]{0,39}$/
//     textHash: "<sha256 hex>",        // Hash des gezeigten Wortlauts; nur bei "widerruf" darf er "" sein
//     kanal: "web_formular" | "portal" | "doi_link" | "abmeldelink" | "backoffice" | "telefon" | "email",
//     land: "DE" | "AT" | "CH" | "unbekannt",
//     zeit?: ISO,                      // Standard: jetzt
//   })  → { id, zeit, hash }
//
//   await werbekanalErlaubt({ email | pseudonym, zweck })   → true | false
//   await werbekanalSicherstellen({ email | pseudonym, zweck }) → true, sonst PlattformFehler 403 „einwilligung_fehlt“
//
//   Regeln der Kanal-Ampel: true NUR nach ausdrücklicher Einwilligung; "newsletter" und "bericht" erst nach einem
//   folgenden Eintrag art "doi"; jeder spätere "widerruf" sperrt wieder. Keine mutmaßliche Einwilligung (auch nicht B2B).
//   Einträge enthalten nie Namen, E-Mail, Telefon oder IP (Muster je Feld, sonst 422).
//
// ── Backoffice (n = angemeldeter Nutzer, Bereich „Vorgänge“) ───────────────────────────────────────────────────
//   leadDesk(n,{land,tage}) · slaBericht(n,{tage}) · leadKetteStatus(n) · widerrufen(n,{vorgangId,zweck,kanal})
//   absageSetzen(n,vorgangId,{code,begruendung}) · personLoeschen(n,{vorgangId,grund}) · kanalStand({email|pseudonym})
//   ipAufraeumen() (Demo: zusätzlich bei jedem Zugriff; Frappe: täglicher Scheduler)

import * as demo from "./demo/leadkette";
import * as frappe from "./frappe/leadkette";
import { backendName, KONFIG_FEHLER } from "./index";
import { PlattformFehler } from "../fehler";

export const LEADKETTE_OPERATIONEN = [
  "protokollAnhaengen", "werbekanalErlaubt", "werbekanalSicherstellen", "kanalStand", "ipAufraeumen",
  "leadDesk", "slaBericht", "leadKetteStatus", "widerrufen", "absageSetzen", "personLoeschen",
];

if (process.env.NODE_ENV !== "production") {
  for (const [name, impl] of [["demo", demo], ["frappe", frappe]]) {
    const fehlt = LEADKETTE_OPERATIONEN.filter((op) => typeof impl[op] !== "function");
    if (fehlt.length) console.warn(`[plattform] Lead-Kette ${name}: fehlende Operationen ${fehlt.join(", ")}`);
  }
}

export function leadketteBackend() {
  const n = backendName();
  if (n === "frappe") return frappe;
  if (n === "demo") return demo;
  throw new PlattformFehler(503, KONFIG_FEHLER);
}

/** Kurzformen (Vertrag oben) */
export const protokollAnhaengen = (eintrag) => leadketteBackend().protokollAnhaengen(eintrag);
export const werbekanalErlaubt = (args) => leadketteBackend().werbekanalErlaubt(args);
export const werbekanalSicherstellen = (args) => leadketteBackend().werbekanalSicherstellen(args);
// src/lib/anfrage/zaehler.js
//
// Server-Zähler für Anfragen OHNE Kennung (Paket C, Welle 1; Masterplan Abschnitt 5 Punkt 6).
// Zählt unabhängig von Cookie-Einwilligung und Google Analytics, weil nichts Personenbezogenes entsteht:
// gezählt wird nur je Tag × Ereignis × Anfragetyp × Land × Kanal. KEINE IP, KEINE E-Mail, KEINE Vorgangs-ID,
// keine Seiten-URL, kein Zeitstempel feiner als der Tag.
//
// Ausgabe: (1) Summen im Arbeitsspeicher des Prozesses (zaehlerStand) und (2) je Ereignis eine
// strukturierte Logzeile „[anfrage-zaehler] {…}“, die das Hosting-Log aufbewahrt und auswertbar macht.
// Dauerhaft gezählt wird zusätzlich im Backend (Demo: db.anfrageZaehler; Frappe: Logger „oekoinvest_anfrage_zaehler“).

import { landNormal } from "./laender.js";

export const ZAEHLER_EREIGNISSE = Object.freeze(["versuch", "angelegt", "abgelehnt", "honeypot"]);
// Kanäle wie in src/lib/herkunft.js (kanal()); Welle 2: „Gruppe“ und „Partner“ (src/lib/gruppe/kanal.js, Paket GRP)
const KANAELE = new Set(["Direkt", "Suchmaschine", "KI-Assistent", "Gruppe", "Partner", "Anzeige", "Social Media", "E-Mail", "Offline/QR", "Kampagne", "Verweis"]);
const TYP_MUSTER = /^[a-z_]{2,30}$/;

const summen = new Map();

/** Tag in Europe/Vienna (gleiche Zeitzone wie das Backoffice), Format JJJJ-MM-TT */
export const tagHeute = (d = new Date()) => d.toLocaleDateString("sv-SE", { timeZone: "Europe/Vienna" });

/** Nur grobe, feste Merkmale – alles Unbekannte wird zu "?" */
export function zaehlerSchluessel({ ereignis, typ, land, kanal, tag = tagHeute() }) {
  return {
    tag,
    ereignis: ZAEHLER_EREIGNISSE.includes(ereignis) ? ereignis : "?",
    typ: typeof typ === "string" && TYP_MUSTER.test(typ) ? typ : "?",
    land: landNormal(land) || "?",
    kanal: typeof kanal === "string" && KANAELE.has(kanal) ? kanal : "?",
  };
}

/** Zählt ein Ereignis. Darf nie werfen (Messung stört keine Anfrage). */
export function anfrageZaehlen(merkmale, { log = true } = {}) {
  try {
    const s = zaehlerSchluessel(merkmale || {});
    const k = `${s.tag}|${s.ereignis}|${s.typ}|${s.land}|${s.kanal}`;
    summen.set(k, (summen.get(k) || 0) + 1);
    if (log) console.info(`[anfrage-zaehler] ${JSON.stringify(s)}`);
    return s;
  } catch {
    return null;
  }
}

/** Aktuelle Summen dieses Prozesses (für Tests und eine spätere Auswertungsroute) */
export function zaehlerStand() {
  return Object.fromEntries(summen);
}

export function _zaehlerLeeren() {
  summen.clear();
}
// POST /api/anfrage – öffentliches Anfrageformular aller Zielgruppen (Vertrag: docs/BRIEFING.md, docs/API.md)
// Erzeugt einen Vorgang; bei typ flaeche/agri zusätzlich einen Flächen-Entwurf.
//
// Paket C (Welle 1):
//  - Keine Pflicht-Einwilligung mehr: Die Bearbeitung stützt sich auf Art. 6 Abs. 1 lit. b DSGVO, das Formular
//    zeigt dazu einen Hinweis (Text, Version und Hash werden beim Vorgang gespeichert). Optionale, getrennte
//    Einwilligungen (body.einwilligungen = { werbeanruf, newsletter, … } nur true/false) werden je Eintrag mit
//    Version und Text-Hash protokolliert. Texte: src/lib/anfrage/hinweise.js (ENTWURF, Strang R).
//    Ältere Clients mit body.einwilligung = true funktionieren weiter.
//  - Rückruf ausdrücklich gewählt (body.rueckruf = true) → Telefon ist Pflicht (serverseitig geprüft).
//  - Server-Zähler ohne Kennung (src/lib/anfrage/zaehler.js): versuch / angelegt / abgelehnt / honeypot.
//
// Welle 2:
//  - Paket GRP: Der Kanal wird serverseitig neu berechnet (herkunftBereinigen, src/lib/gruppe/kanal.js); eine
//    Partner-/Gruppenkennung wird nur übernommen, wenn sie im Register wirksam ist.
//  - Paket B3: Land (Pflicht, sonst „unbekannt“), Routing, Score, SLA-Klasse, getrennte Personendaten und das
//    Einwilligungsprotokoll entstehen im Backend (anfrageAnlegen → demo/leadkette.js bzw. Frappe einwilligung.py).
//    Personendaten stehen nie in Logs oder Fehlermeldungen dieser Route.

import { createHash } from "node:crypto";
import { route } from "@/lib/plattform/server/route";
import { PlattformFehler } from "@/lib/plattform/fehler";
import { HINWEIS, einwilligungenAufbereiten, hinweisText } from "@/lib/anfrage/hinweise";
import { anfrageLand } from "@/lib/anfrage/laender";
import { anfrageZaehlen } from "@/lib/anfrage/zaehler";
import { herkunftBereinigen } from "@/lib/gruppe/kanal";

const sha256 = (s) => createHash("sha256").update(String(s)).digest("hex");
const objekt = (x) => (x && typeof x === "object" && !Array.isArray(x) ? x : {});

export const POST = route({ auth: "optional", limit: "anfrage", maxBytes: 48 * 1024 }, async ({ body, backend, ip, nutzer }) => {
  const kontakt = objekt(body.kontakt);
  const daten = objekt(body.daten);
  const herkunftRoh = objekt(body.herkunft);
  const { kanal, partnerKennung } = herkunftBereinigen(herkunftRoh); // GRP: Kanal nie vom Browser übernehmen
  const herkunft = { ...herkunftRoh, kanal, partnerKennung };
  const merkmale = { typ: body.typ, land: anfrageLand(kontakt, daten), kanal };

  if (body.website) {
    anfrageZaehlen({ ...merkmale, ereignis: "honeypot" });
    return { ok: true, id: "", vorgang: null }; // Honeypot: still verwerfen
  }
  anfrageZaehlen({ ...merkmale, ereignis: "versuch" });

  try {
    const telefon = typeof kontakt.telefon === "string" ? kontakt.telefon.trim() : "";
    const rueckruf = body.rueckruf === true;
    if (rueckruf && !telefon) throw new PlattformFehler(422, "Für einen Rückruf brauchen wir Ihre Telefonnummer.");
    const am = new Date().toISOString();
    const sprache = daten.sprache === "en" ? "en" : "de"; // /en-Formulare zeigen den englischen Wortlaut
    const ergebnis = await backend.anfrageAnlegen({
      typ: body.typ,
      kontakt,
      daten: { ...daten, rueckrufGewuenscht: rueckruf },
      herkunft,
      ip,
      einwilligungText: hinweisText(sprache),
      hinweis: { id: HINWEIS.id, version: HINWEIS.version, rechtsgrundlage: HINWEIS.rechtsgrundlage, textHash: sha256(hinweisText(sprache)) },
      einwilligungen: einwilligungenAufbereiten(body.einwilligungen, { hash: sha256, am, telefon, sprache }),
      nutzer,
    });
    anfrageZaehlen({ ...merkmale, land: ergebnis.vorgang?.land || merkmale.land, ereignis: "angelegt" });
    return { ok: true, id: ergebnis.id, vorgang: ergebnis.vorgang };
  } catch (e) {
    anfrageZaehlen({ ...merkmale, ereignis: "abgelehnt" });
    throw e;
  }
});

// src/lib/plattform/backend/index.js
//
// Einheitliche Backend-Schnittstelle der Plattform. Zwei Implementierungen:
//   frappe.js – Frappe-App `oekoinvest_app` (Produktion), Auswahl mit PLATTFORM_BACKEND=frappe
//   demo.js   – JSON-Datei unter .data/plattform.json (Entwicklung/Vorführung)
//
// Im Produktions-Build wird das Demo-Backend NUR genutzt, wenn PLATTFORM_DEMO=1 gesetzt ist –
// sonst gibt es eine klare Fehlermeldung (HTTP 503) statt stiller Demo-Daten.
//
// Nur serverseitig verwenden (Route-Handler, Server-Komponenten).
//
// Alle Operationen (Signaturen identisch in beiden Implementierungen; n = angemeldeter Nutzer):
//   Konto:     anmelden({email,passwort}) · nutzerFuerSitzung(id) · registrieren({...}) · emailBestaetigen({token})
//              passwortVergessen({email,basisUrl,ip}) · passwortSetzen({token,passwort,ip}) · passwortAendern(n,{alt,neu})
//              profilSpeichern(n,daten) · suchprofilSpeichern(n,profil)
//   Anfrage:   anfrageAnlegen({typ,kontakt,daten,herkunft,ip,einwilligungText,nutzer})
//   Vorgänge:  vorgaenge(n,{alle,status,typ,q}) · vorgang(n,id)
//   Flächen:   flaechen(n,{alle,status}) · flaeche(n,id) · flaecheAnlegen(n,daten,{ip}) · flaecheAendern(n,id,daten)
//   Projekte:  projekte(n,{alle,status}) · projekt(n,id) · projektAnlegen(n,daten,{ip}) · projektAendern(n,id,daten)
//              provisionAkzeptieren(n,id,{ip})
//   Börse:     boerse(n|null,filter) · boerseDetail(n|null,slugOderId,{zaehlen})
//   Interesse: merken(n,projektId,an) · ndaAnfragen(n,projektId,{akzeptiert,ip,userAgent}) · interessen(n,{alle,status,projektId})
//   Prozess:   statusWechsel(n,{art,id,nach,als,extra,ip})
//   Nachricht: nachrichtenThreads(n) · nachrichten(n,bezugArt,bezugId,{markieren}) · nachrichtSenden(n,{bezugArt,bezugId,text})
//   Dokument:  dokumente(n,{bezugArt,bezugId}) · dokumentLesen(n,id) · dokumentSpeichern(n,{...,daten}) · dokumentLoeschen(n,id)
//   Admin:     zuweisen · nutzerListe · nutzerAendern · provisionen · aktivitaeten · adminKonten · adminUebersicht · demoLinks
//   Hinweise:  benachrichtigungen(n,{nurUngelesen,limit}) · benachrichtigungenGelesen(n,{ids,alle}) · mailEinstellungenSpeichern(n,einstellungen)
//   Aufgaben:  aufgaben(n,{zustaendigId,status,bezugArt,bezugId,nurUeberfaellig}) · aufgabeAnlegen(n,daten) · aufgabeAendern(n,id,daten)
//   Exposé:    exposeDaten(n,id,{ip}) (Rechte + Protokoll, PDF erzeugt die Website) · protokollEintrag(n,{aktion,objektArt,objektId,text,ip})
//   Nur Demo:  postausgang(n,{limit}) (E-Mails, die Frappe versenden würde; im Frappe-Adapter [])

import * as demo from "./demo";
import * as frappe from "./frappe";
import { PlattformFehler } from "../fehler";
import { BACKOFFICE_OPERATIONEN } from "./frappe/backoffice";
import { demoPruefung } from "../demoGuard";

export const OPERATIONEN = [
  "anmelden", "nutzerFuerSitzung", "registrieren", "emailBestaetigen", "passwortVergessen", "passwortSetzen", "passwortAendern",
  "profilSpeichern", "suchprofilSpeichern", "anfrageAnlegen", "vorgaenge", "vorgang", "flaechen", "flaeche", "flaecheAnlegen",
  "flaecheAendern", "projekte", "projekt", "projektAnlegen", "projektAendern", "provisionAkzeptieren", "boerse", "boerseDetail",
  "merken", "ndaAnfragen", "interessen", "statusWechsel", "nachrichtenThreads", "nachrichten", "nachrichtSenden", "dokumente",
  "dokumentLesen", "dokumentSpeichern", "dokumentLoeschen", "zuweisen", "nutzerListe", "nutzerAendern", "provisionen",
  "aktivitaeten", "adminKonten", "adminUebersicht", "demoLinks", "benachrichtigungen", "benachrichtigungenGelesen",
  "mailEinstellungenSpeichern", "postausgang", "aufgaben", "aufgabeAnlegen", "aufgabeAendern", "exposeDaten", "protokollEintrag",
  ...BACKOFFICE_OPERATIONEN, // Backoffice: CRM, Akquise, Automationen, Vorlagen, Berichte, Rechte (backend/frappe/backoffice.js)
];

if (process.env.NODE_ENV !== "production") {
  for (const [name, impl] of [["demo", demo], ["frappe", frappe]]) {
    const fehlt = OPERATIONEN.filter((op) => typeof impl[op] !== "function");
    if (fehlt.length) console.warn(`[plattform] Backend ${name}: fehlende Operationen ${fehlt.join(", ")}`);
  }
}

export const KONFIG_FEHLER =
  "Das Plattform-Backend ist nicht konfiguriert. Für den Betrieb PLATTFORM_BACKEND=frappe setzen (siehe docs/PLATTFORM.md) – oder PLATTFORM_DEMO=1 für eine reine Vorführung.";

let demoSperreGemeldet = false;

export function backendName() {
  if (process.env.PLATTFORM_BACKEND === "frappe") return "frappe";
  // Demo-Guard (Paket A): im Produktions-Build nie auf der Produktionsdomain, nie ohne Basis-URL
  const pruefung = demoPruefung();
  if (!pruefung.erlaubt) {
    if (process.env.PLATTFORM_DEMO === "1" && !demoSperreGemeldet) {
      demoSperreGemeldet = true;
      console.error(`[plattform] Demo-Backend gesperrt: ${pruefung.grund}`);
    }
    return null;
  }
  return "demo";
}

/** Liefert die aktive Implementierung oder wirft 503 */
export function backend() {
  const n = backendName();
  if (n === "frappe") return frappe;
  if (n === "demo") return demo;
  throw new PlattformFehler(503, KONFIG_FEHLER);
}

export const istDemo = () => backendName() === "demo";
