      grenzen: { ha: [1, 100], proHa: [1000, 5000], umsatzPct: [3, 10], mindestProHa: [0, 3000], laufzeit: [20, 40], ackerProHa: [100, 1200], dbProHa: [0, 1500], vorlaufJahre: [1, 4] },
    }
