      wert={regionId}
      onChange={setRegionId}
      spalten={3}
      klein
      optionen={REGIONEN.map((x) => ({ id: x.id, label: REGION_KURZ[x.id] || x.label, sub: `${fmt(x.ertrag)} kWh/kWp` }))}
