import Link from "next/link";
import { ArrowRight, LoaderCircle } from "lucide-react";
import { cn } from "./cn";

const VARIANTEN = {
  primary:
    "bg-ov-600 text-white shadow-[0_8px_24px_-8px_rgba(102,153,51,0.65)] hover:bg-ov-700 hover:shadow-[0_12px_32px_-8px_rgba(102,153,51,0.75)]",
  navy: "bg-navy-700 text-white hover:bg-navy-800 shadow-[0_8px_24px_-10px_rgba(0,52,115,0.6)]",
  secondary:
    "bg-white text-ink-900 ring-1 ring-inset ring-ink-200 hover:ring-ink-300 hover:bg-ink-50",
  ghost: "text-ink-800 hover:bg-ink-100",
  white: "bg-white text-navy-900 hover:bg-ov-50 shadow-[0_8px_30px_-10px_rgba(0,0,0,0.4)]",
  outlineLight:
    "text-white ring-1 ring-inset ring-white/35 hover:bg-white/10 hover:ring-white/60 backdrop-blur-sm",
  sun: "bg-sun-400 text-navy-950 hover:bg-sun-300 shadow-[0_10px_30px_-10px_rgba(245,167,15,0.7)]",
  // Design-System 2.0
  danger: "bg-danger-600 text-white hover:bg-danger-700 shadow-[0_8px_24px_-10px_rgba(184,53,42,0.6)]",
  dangerLeise: "bg-white text-danger-700 ring-1 ring-inset ring-danger-200 hover:bg-danger-50",
  link: "h-auto px-0 text-ov-700 underline-offset-4 hover:text-ov-800 hover:underline",
};

const GROESSEN = {
  xs: "h-8 px-3 text-[13px] gap-1.5 rounded-full",
  sm: "h-10 px-4 text-[14px] gap-1.5 rounded-full",
  md: "h-12 px-6 text-[15px] gap-2 rounded-full",
  lg: "h-14 px-8 text-[16px] gap-2.5 rounded-full",
};

/**
 * Einheitlicher Button. Mit `href` wird ein Link gerendert (intern via
 * next/link, extern/tel/mailto als <a>), sonst ein <button>.
 *
 * variant: primary | navy | secondary | ghost | white | outlineLight | sun | danger | dangerLeise | link
 * size:    xs | sm | md | lg
 * laedt:   zeigt einen Spinner, sperrt den Button (aria-busy), Breite bleibt stabil
 * block:   volle Breite
 * pfeil:   Pfeil rechts, gleitet bei Hover und Tastaturfokus nach rechts
 * magnetisch: folgt dem Mauszeiger um wenige Pixel (nur EIN Haupt-CTA pro Ansicht,
 *          siehe @/components/motion/Magnetisch)
 *
 * Feedback: Hover (Farbe/Schatten 200 ms), Druck (scale 0.975, 75 ms), Fokusring rastet ein.
 */
export default function Button({
  href,
  variant = "primary",
  size = "md",
  pfeil = false,
  icon: Icon,
  laedt = false,
  block = false,
  magnetisch = false,
  className,
  children,
  ...rest
}) {
  const klassen = cn(
    "group relative inline-flex select-none items-center justify-center whitespace-nowrap font-semibold tracking-[-0.005em] transition-[color,background-color,box-shadow,scale,translate,opacity,outline-offset] duration-200 ease-ov-out active:scale-[0.975] active:duration-75 disabled:opacity-50",
    VARIANTEN[variant] || VARIANTEN.primary,
    variant === "link" ? "gap-1.5 text-[15px]" : GROESSEN[size] || GROESSEN.md,
    block && "w-full",
/**
 * Motion-System 3 – ein Import-Pfad für alle Bewegungs-Primitive.
 *
 *   import { TextEnthuellung, Zaehler, PfadZeichnen, Spotlight } from "@/components/motion";
 *
 * Server-taugliche Bausteine (kein Client-JS): TextEnthuellung, PfadZeichnen, Parallax,
 * Spotlight, Magnetisch, KippKarte, Einblenden (= ui/Reveal), Gruppe (= ui/Stagger).
 * Client-Bausteine: Zaehler, ScrollFortschritt, Laufband (= ui/Marquee).
 * Global eingebunden (LayoutWrapper, nicht selbst einbinden): MotionInteraktion, RevealObserver.
 * Hilfen für eigene Client-Logik: useFreieUnterkante (feste Leisten unten) sowie – direkt aus
 * "@/components/ui/motion" importieren – DAUER, KURVE, useReduzierteBewegung, useSichtbar,
 * mitUebergang, signal.
 */
export { default as TextEnthuellung } from "./TextEnthuellung";
export { default as Zaehler } from "./Zaehler";
export { default as PfadZeichnen } from "./PfadZeichnen";
export { default as Parallax } from "./Parallax";
export { default as Spotlight } from "./Spotlight";
export { default as Magnetisch } from "./Magnetisch";
export { default as KippKarte } from "./KippKarte";
export { default as ScrollFortschritt } from "./ScrollFortschritt";
export { default as useFreieUnterkante } from "./useFreieUnterkante";
export { default as Einblenden } from "@/components/ui/Reveal";
export { default as Gruppe } from "@/components/ui/Stagger";
export { default as Laufband } from "@/components/ui/Marquee";
import { cn } from "./cn";

/**
 * Badge / Status-Chip des Design-Systems 2.0.
 *
 * ton:   neutral | info | success (= ok) | warn | danger | marke | navy | dunkel | glas
 * groesse: sm | md
 * punkt:   farbiger Statuspunkt davor; live = pulsierender Punkt (Live-Daten)
 * icon:    Lucide-Icon statt Punkt
 *
 * Text immer ≥ 4.5:1 auf dem Hintergrund (geprüft, siehe DESIGN.md).
 * Status nie nur über Farbe: Beschriftung ist Pflicht.
 */
export const BADGE_TOENE = {
  neutral: { flaeche: "bg-ink-100 text-ink-700 ring-ink-200", punkt: "bg-ink-400" },
  info: { flaeche: "bg-navy-50 text-navy-700 ring-navy-100", punkt: "bg-navy-500" },
  success: { flaeche: "bg-ov-50 text-ov-800 ring-ov-200", punkt: "bg-ov-500" },
  ok: { flaeche: "bg-ov-50 text-ov-800 ring-ov-200", punkt: "bg-ov-500" },
  warn: { flaeche: "bg-sun-50 text-sun-700 ring-sun-200", punkt: "bg-sun-500" },
  danger: { flaeche: "bg-danger-50 text-danger-700 ring-danger-200", punkt: "bg-danger-500" },
  marke: { flaeche: "bg-ov-600 text-white ring-ov-700/40", punkt: "bg-white" },
  navy: { flaeche: "bg-navy-700 text-white ring-navy-800", punkt: "bg-ov-300" },
  dunkel: { flaeche: "bg-white/10 text-white ring-white/15", punkt: "bg-ov-300" },
  glas: { flaeche: "ov-glass text-white ring-transparent", punkt: "bg-ov-300" },
};

export default function Badge({ ton = "neutral", groesse = "md", punkt = false, live = false, icon: Icon, className, children, ...rest }) {
  const t = BADGE_TOENE[ton] || BADGE_TOENE.neutral;
  return (
    <span
      className={cn(
        "inline-flex items-center whitespace-nowrap rounded-full font-semibold ring-1 ring-inset",
        groesse === "sm" ? "gap-1 px-2 py-0.5 text-[11.5px]" : "gap-1.5 px-2.5 py-1 text-[12px]",
        t.flaeche,
        className
      )}
      {...rest}
    >
      {Icon ? (
        <Icon aria-hidden="true" className={groesse === "sm" ? "h-3 w-3" : "h-3.5 w-3.5"} />

